import React, { useState, useEffect, useRef, useCallback } from "react";
import * as Tone from "tone";

const PHOTO_SRC = "data:image/jpeg;base64,";

/* ---- Personalisation: one card, many teachers ----
   Share a link like  ...?teacher=pooja  and this file will
   look up that key below and render their name/photo/role.
   Add a new teacher by adding another entry here. If "photo"
   is left empty, a soft initials badge is shown instead. */
const TEACHERS = {
  pooja: {
    name: "Pooja Patil",
    role: "Department of Computer Engineering",
    photo: PHOTO_SRC,
  },
  // anita: {
  //   name: "Anita Desai",
  //   role: "Department of Mechanical Engineering",
  //   photo: "https://your-image-host.com/anita.jpg",
  // },
};

function useTeacherFromLink() {
  const [teacher, setTeacher] = useState(TEACHERS.pooja);
  useEffect(() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const key = (params.get("teacher") || params.get("id") || "pooja").toLowerCase();
      setTeacher(TEACHERS[key] || TEACHERS.pooja);
    } catch (e) {
      /* no query params available, fall back to default */
    }
  }, []);
  return teacher;
}

function initialsOf(name) {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0].toUpperCase())
    .join("");
}

function Corner() {
  return (
    <svg width="30" height="30" viewBox="0 0 34 34" fill="none">
      <path d="M2 32 Q2 2 32 2" stroke="#B27F2E" strokeWidth="1" opacity="0.6" />
      <circle cx="6" cy="27" r="3.2" fill="#E8722E" />
      <circle cx="10" cy="21" r="2.4" fill="#F0A93E" />
      <circle cx="15" cy="15" r="2" fill="#E8722E" />
      <circle cx="21" cy="10" r="2.4" fill="#F0A93E" />
      <circle cx="27" cy="6" r="3" fill="#E8722E" />
    </svg>
  );
}
function Corner_TL() { return <div className="td-corner tl"><Corner /></div>; }
function Corner_TR() { return <div className="td-corner tr"><Corner /></div>; }
function Corner_BL() { return <div className="td-corner bl"><Corner /></div>; }
function Corner_BR() { return <div className="td-corner br"><Corner /></div>; }

